#include "stdlib/blas/base/shared/cblas.h"
#include "stdlib/blas/ext/base/ndarray/dtril.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

#define NAME "dtril"
#define ITERATIONS 1000000
#define REPEATS 3
#define MIN 1
#define MAX 6

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total ); // TAP plan
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmarks results.
*
* @param iterations  number of iterations
* @param elapsed     elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %0.9f\n", elapsed );
	printf( "  rate: %0.9f\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Generates a random number on the interval [min,max).
*
* @param min    minimum value (inclusive)
* @param max    maximum value (exclusive)
* @return random number
*/
static double random_uniform( const double min, const double max ) {
	double v = (double)rand() / ( (double)RAND_MAX + 1.0 );
	return min + ( v*(max-min) );
}

/**
* Runs a benchmark.
*
* @param iterations   number of iterations
* @param len          array length
* @return             elapsed time in seconds
*/
static double benchmark( int iterations, int N ) {
	enum STDLIB_NDARRAY_INDEX_MODE imode;
	const struct ndarray *arrays[ 3 ];
	enum STDLIB_NDARRAY_ORDER order;
	int8_t submodes[ 2 ];
	int64_t strides[ 2 ];
	int64_t k_strides[ 1 ];
	int64_t shape[ 2 ];
	int64_t nsubmodes;
	struct ndarray *A;
	struct ndarray *B;
	struct ndarray *k;
	int64_t offset;
	double elapsed;
	int64_t ndims;
	double *dataA;
	double *dataB;
	CBLAS_INT k_data[ 1 ];
	double t;
	int i;

	ndims = 2;
	shape[ 0 ] = N;
	shape[ 1 ] = N;
	strides[ 0 ] = (int64_t)N * STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT;
	strides[ 1 ] = STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT;
	k_strides[ 0 ] = 0;
	offset = 0;
	order = STDLIB_NDARRAY_ROW_MAJOR;
	imode = STDLIB_NDARRAY_INDEX_ERROR;
	submodes[ 0 ] = imode;
	submodes[ 1 ] = imode;
	nsubmodes = 2;

	dataA = (double *) malloc( N * N * sizeof( double ) );
	dataB = (double *) malloc( N * N * sizeof( double ) );
	for ( i = 0; i < N*N; i++ ) {
		dataA[ i ] = random_uniform( -10.0, 10.0 );
		dataB[ i ] = 0.0;
	}

	// cppcheck-suppress invalidPointerCast
	A = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataA, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );

	// cppcheck-suppress invalidPointerCast
	B = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataB, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );

	k_data[ 0 ] = 0;
	ndims = 0;

	k = stdlib_ndarray_allocate( STDLIB_NDARRAY_INT32, (uint8_t *)k_data, ndims, NULL, k_strides, offset, order, imode, 1, submodes);
	arrays[ 0 ] = A;
	arrays[ 1 ] = B;
	arrays[ 2 ] = k;

	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		stdlib_blas_ext_dtril( arrays );
		if ( dataB[ 0 ] != dataB[ 0 ] ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = tic() - t;
	if ( dataB[ 0 ] != dataB[ 0 ] ) {
		printf( "should not return NaN\n" );
	}
	stdlib_ndarray_free( A );
	stdlib_ndarray_free( B );
	stdlib_ndarray_free( k );
	free( dataA );
	free( dataB );
	arrays[ 0 ] = NULL;
	arrays[ 1 ] = NULL;

	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int N;
	int i;
	int j;

	// Use the current time to seed the random number generator:
	srand( time( NULL ) );

	print_version();
	count = 0;
	for ( i = MIN; i <= MAX; i++ ) {
		len = pow( 10, i );
		N = (int)sqrt( (double)len );
		iter = ITERATIONS / pow( 10, i-1 );
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s::square_matrix:order=row-major,size=%d\n", NAME, N*N );
			elapsed = benchmark( iter, N );
			print_results( iter, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	print_summary( count, count );
}
